  FROM (SELECT 'DMF0005_REPORT_GROUP6' SQL_ID, 'DM' MDU_DIVS_CD, '[B] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''DMF0005_REPORT_GROUP6''' SQL_NM, 'SELECT L.SEGMENT1 AS CODE , L.SEGMENT2 AS NAME FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE 1 = 1 AND L.LOOKUP_TYPE = ''REPORT_GROUP6'' AND L.VALID_YN = ''Y''' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
