SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'DMF0044_DEPARTMENT_TEAM2' SQL_ID, 'DM' MDU_DIVS_CD, '[C] AS-IS @Code=''DMF0044_DEPARTMENT_TEAM2'' 수작업 통합 변환 — division별 LOOKUP_TYPE CASE ' SQL_NM, 'SELECT L.SEGMENT1 AS CODE, L.SEGMENT2 AS NAME FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.VALID_YN = ''Y'' AND L.LOOKUP_TYPE = CASE WHEN NVL(TRIM(@divisionId), ''40'') = ''40'' THEN ''DMF0044_DEPARTMENT_TEAM2'' ELSE ''DMF0044_DEPARTMENT_TEAM2_'' || RTRIM(@divisionId) END ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
