SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'DMF0044_MDF_DEPARTMENT' SQL_ID, 'DM' MDU_DIVS_CD, '[B] AS-IS @Code=''DMF0044_MDF_DEPARTMENT'' 수작업 통합 변환 — division별 LOOKUP_TYPE CASE ' SQL_NM, 'SELECT L.SEGMENT1 AS CODE' || CHR(13) || CHR(10) || '     , L.SEGMENT2 AS NAME' || CHR(13) || CHR(10) || '  FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L' || CHR(13) || CHR(10) || ' WHERE L.VALID_YN = ''Y''' || CHR(13) || CHR(10) || '   AND L.LOOKUP_TYPE = CASE' || CHR(13) || CHR(10) || '                       WHEN NVL(TRIM(@divisionId), ''40'') = ''40'' THEN ''MDF_DEPARTMENT''' || CHR(13) || CHR(10) || '                       ELSE ''MDF_DEPARTMENT_'' || RTRIM(@divisionId)' || CHR(13) || CHR(10) || '                       END' || CHR(13) || CHR(10) || '   AND ( NVL(TRIM(@divisionId), ''40'') <> ''40''' || CHR(13) || CHR(10) || '         OR L.SEGMENT3 = ''Y'' )   /* 40 : GDW_YN(SEGMENT3) 가 Y 인 행만 — 이 화면 표시 담당 여부. 81·82 는 그 칸이 ''-'' 라 적용 제외 */' || CHR(13) || CHR(10) || ' ORDER BY DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
