  FROM (SELECT 'DM_LOOKUP_DIV' SQL_ID, 'DM' MDU_DIVS_CD, '[C] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''DM_LOOKUP_DIV'' — ⚠ @param1(SEGMENT1)/@param' SQL_NM, 'SELECT B.SEGMENT2 CODE ,B.SEGMENT3 NAME FROM SCM_ADM_LOOKUP_MASTER A INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = ''Y'' WHERE A.LOOKUP_TYPE = @param2 AND B.SEGMENT1 = @param1 AND A.VALID_YN = ''Y'' ORDER BY B.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
