  FROM (SELECT 'Division' SQL_ID, 'ALL' MDU_DIVS_CD, 'Division 조회' SQL_NM, 'SELECT DIVISION_ID AS CODE , DIVISION_ID AS NAME FROM SCM_MST_DIVISION WHERE ( @param1 IS NULL OR DIVISION_ID LIKE ''%'' || @param1 || ''%'' ) OR ( @param1 IS NULL OR DIVISION_NAME LIKE ''%'' || @param1 || ''%'' ) GROUP BY DIVISION_ID ORDER BY UPPER(DIVISION_ID)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
