SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'END_CUST_REPORT' SQL_ID, 'DM' MDU_DIVS_CD, '[B] AS-IS asis_sp_UP_FX_GetCommonDataList.sql @Code=''EndCustReport''' SQL_NM, 'SELECT B.SEGMENT1 CODE ,B.SEGMENT2 NAME FROM SCM_ADM_LOOKUP_MASTER A INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = ''Y'' WHERE A.LOOKUP_TYPE = ''END_CUST_REPORT'' AND A.VALID_YN = ''Y'' ORDER BY B.DISPLAY_SEQ, UPPER(CODE)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'EndCustomerByDivisionDept' SQL_ID, 'DM' MDU_DIVS_CD, 'End Customer by division, team (40=PROJECT_CODE, 빈값 제외, 권한 복구)' SQL_NM, 'SELECT *' || CHR(10) || '  FROM (' || CHR(10) || 'SELECT DISTINCT A.END_CUSTOMER AS CODE , NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM SCM_MST_SITE A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.DIVISION_ID = D.SEGMENT1 AND A.END_CUSTOMER = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'' WHERE 1 = 1 AND ( @divisionId IS NULL OR @divisionId = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0 ) AND ( @deptId IS NULL OR @deptId = ''ALL'' OR EXISTS ( SELECT 1 FROM SCM_MST_SITE_ITEM SA WHERE SA.DIVISION_ID = A.DIVISION_ID AND SA.SCM_SITE_ID = A.SCM_SITE_ID AND INSTR('','' || @deptId || '','', '','' || SA.DEPT_ID || '','') > 0 ) ) AND A.DIVISION_ID IN ( SELECT U.UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U WHERE U.UNIT_TP_CD = ''D'' AND U.USE_YN = ''Y'' AND U.USER_GR_ID IN ( SELECT G.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USE_YN = ''Y'' ) AND U.USER_ID = @sesUserId ) AND A.END_CUSTOMER IS NOT NULL UNION SELECT  SEGMENT2                AS CODE      ,  NVL(SEGMENT3, SEGMENT2) AS NAME   FROM  SCM_ADM_LOOKUP_MASTER_DETAIL  WHERE  SEGMENT1 IN ( SELECT U.UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M U WHERE U.UNIT_TP_CD = ''D'' AND U.USE_YN = ''Y'' AND U.USER_GR_ID IN ( SELECT G.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M G WHERE G.USER_ID = @sesUserId AND G.USE_YN = ''Y'' ) AND U.USER_ID = @sesUserId )    AND  LOOKUP_TYPE = ''END_CUSTOMER''    AND  VALID_YN    = ''Y''    AND  SEGMENT2   <> ''-''    AND  SEGMENT1   <> ''40''    AND  ( @divisionId IS NULL OR @divisionId = ''ALL''           OR INSTR('','' || @divisionId || '','', '','' || SEGMENT1 || '','') > 0 )    AND  ( @deptId IS NULL OR @deptId = ''ALL'' )' || CHR(10) || '       )' || CHR(10) || ' ORDER BY UPPER(CODE)' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'FCST_TYPE' SQL_ID, 'DM' MDU_DIVS_CD, '[PJ20209643] W/S 프로세스 -- FCST Type 권한 정리' SQL_NM, 'WITH WT_INPUT AS (' || CHR(13) || CHR(10) || '	SELECT CASE WHEN A.USER_GR_ID = ''DM Planner (W/S)'' AND NVL(@editModeYn,''N'') = ''Y'' THEN ''Y'' ELSE ''N'' END AS EDIT_MODE_YN' || CHR(13) || CHR(10) || '	     , CASE WHEN A.USER_GR_ID = ''DM Planner (W/S)'' THEN ''Y'' ELSE ''N'' END DM_PLAN_WS_YN' || CHR(13) || CHR(10) || '	     , A.USER_GR_ID ' || CHR(13) || CHR(10) || '	     , A.USE_YN ' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_USER_GR_MPG_M A' || CHR(13) || CHR(10) || '	WHERE  A.USER_ID = @sesUserId' || CHR(13) || CHR(10) || '	AND    A.USE_YN = ''Y''' || CHR(13) || CHR(10) || ')' || CHR(13) || CHR(10) || 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || 'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || 'WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2''' || CHR(13) || CHR(10) || 'AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || 'AND    EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '               FROM   WT_INPUT' || CHR(13) || CHR(10) || '               WHERE  DM_PLAN_WS_YN = ''Y'')' || CHR(13) || CHR(10) || 'UNION ' || CHR(13) || CHR(10) || 'SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || 'FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || 'WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE''' || CHR(13) || CHR(10) || 'AND    NVL(ATTRIBUTE2,''N'') <> ''Y''' || CHR(13) || CHR(10) || 'AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || 'AND    EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '               FROM   WT_INPUT' || CHR(13) || CHR(10) || '               WHERE  DM_PLAN_WS_YN = ''N'')' || CHR(13) || CHR(10) || 'UNION' || CHR(13) || CHR(10) || 'SELECT CODE, NAME' || CHR(13) || CHR(10) || 'FROM' || CHR(13) || CHR(10) || '(' || CHR(13) || CHR(10) || '	SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || '	WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2''' || CHR(13) || CHR(10) || '	AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || '	UNION ALL' || CHR(13) || CHR(10) || '	SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME' || CHR(13) || CHR(10) || '	FROM   SCM_ADM_LOOKUP_MASTER_DETAIL A ' || CHR(13) || CHR(10) || '	WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE2_ADD''' || CHR(13) || CHR(10) || '	AND    VALID_YN = ''Y''' || CHR(13) || CHR(10) || ') A' || CHR(13) || CHR(10) || 'WHERE EXISTS (SELECT 1 ' || CHR(13) || CHR(10) || '              FROM   WT_INPUT' || CHR(13) || CHR(10) || '              WHERE  EDIT_MODE_YN = ''Y'')' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
